from math import gcd
from functools import reduce

def transform(grid):
    a=[row[:] for row in grid]
    H,W=len(a),len(a[0])
    pts=[(r,c) for r in range(H) for c in range(W) if a[r][c] in (1,2,3,4)]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    key=[row[c0:c1+1] for row in a[r0:r1+1]]
    rot=[list(row) for row in zip(*key[::-1])]
    cells=[(r,c) for r in range(H) for c in range(W) if a[r][c]==8]
    ar0,ar1=min(r for r,c in cells),max(r for r,c in cells)
    ac0,ac1=min(c for r,c in cells),max(c for r,c in cells)
    runs=[]
    for r in range(H):
        vals=[c for c in range(W) if a[r][c]==8]
        if vals:
            st=pr=vals[0]
            for c in vals[1:]:
                if c!=pr+1:
                    runs.append(pr-st+1);st=c
                pr=c
            runs.append(pr-st+1)
    for c in range(W):
        vals=[r for r in range(H) if a[r][c]==8]
        if vals:
            st=pr=vals[0]
            for r in vals[1:]:
                if r!=pr+1:
                    runs.append(pr-st+1);st=r
                pr=r
            runs.append(pr-st+1)
    scale=reduce(gcd,runs)
    n=len(rot)
    for i in range(n):
        for j in range(n):
            color=rot[i][j]
            if color:
                for r in range(ar0+i*scale,ar0+(i+1)*scale):
                    for c in range(ac0+j*scale,ac0+(j+1)*scale):
                        if a[r][c]==8:
                            a[r][c]=color
    return a

# Build and test both demonstration pairs from their macro-cell descriptions.
def build_demo(h,w,keypos, macro, scale):
    g=[[0]*w for _ in range(h)]
    for (r,c),v in keypos.items(): g[r][c]=v
    cells=[(i,j) for i,row in enumerate(macro) for j,x in enumerate(row) if x]
    br=min(i for i,j in cells); bc=min(j for i,j in cells)
    for i,j in cells:
        for r in range(br+i*scale,br+(i+1)*scale):
            for c in range(bc+j*scale,bc+(j+1)*scale):g[r][c]=8
    return g
